    final origin = _webOrigin;
    if (origin == null) {
      throw StateError('This app shares page links, so its runtime config must carry its web origin.');
    }
    return Uri.parse('${origin.origin}${_nav.url(pathTemplate, args)}');
  }

  Future<void> text(Message message) => shareText(message.text);

  /// `Share.file(bytes, filename, contentType)`: shares [bytes] (a route's raw answer or a
  /// field's base64 text, [cruftfreeBytesOf]) as one file named [filename] of [contentType].
