/// What the connectivity rule observes.
enum ConnectivityEvent { networkLost, networkFound, probeAnswered, probeUnanswered, readUnreachable }

/// Whether a network is up, and whether the API origin answered the last check.
@immutable
class ConnectivityState {
  const ConnectivityState({required this.network, required this.reachable});

  /// The state the runtime starts in: the origin is assumed reachable until a
  /// check says otherwise.
  const ConnectivityState.initial(this.network) : reachable = true;

  final bool network;
  final bool reachable;

  /// `Device.isOnline` in this state.
  bool get isOnline => network && reachable;
}

/// The state an event leads to, and whether a probe is sent because of it.
typedef ConnectivityStep = ({ConnectivityState state, bool probe});

/// The state [event] leads to from [state], and whether a probe is sent now.
ConnectivityStep connectivityStep(ConnectivityState state, ConnectivityEvent event) => switch (event) {
  ConnectivityEvent.networkLost => (state: ConnectivityState(network: false, reachable: state.reachable), probe: false),
  ConnectivityEvent.networkFound => (state: ConnectivityState(network: true, reachable: state.reachable), probe: true),
  ConnectivityEvent.probeAnswered => (state: ConnectivityState(network: state.network, reachable: true), probe: false),
  ConnectivityEvent.probeUnanswered => (state: ConnectivityState(network: state.network, reachable: false), probe: false),
  ConnectivityEvent.readUnreachable => (state: ConnectivityState(network: state.network, reachable: false), probe: state.network),
};

/// How long a probe waits for an answer before it counts as unanswered.
const Duration connectivityProbeTimeout = Duration(milliseconds: 5000);

/// How long after an unanswered probe the next one is sent, while the network stays up.
const Duration connectivityRecheck = Duration(milliseconds: 15000);

/// The one address a probe asks: the root of the configured API origin.
Uri connectivityProbeAddress(Uri apiBaseUrl) => Uri(scheme: apiBaseUrl.scheme, host: apiBaseUrl.host, port: apiBaseUrl.hasPort ? apiBaseUrl.port : null, path: '/');

/// Asks [address] whether it answers: a `HEAD` request carrying no credential
/// and following no redirect, whose answer is never read. Any HTTP answer
/// within [timeout] is `true`; a network error, or no answer in time, is `false`.
Future<bool> probeOrigin(http.Client client, Uri address, Duration timeout) async {
  final request = http.Request('HEAD', address)..followRedirects = false;
  try {
    final response = await client.send(request).timeout(timeout);
    await response.stream.drain<void>();
    return true;
  } on Exception {
    return false;
  }
}

/// `Device.isOnline`: whether the device has a network and the configured API
/// origin answered the last check, as one Boolean a view reads (listening to it
/// rebuilds when it changes). The network going down makes it `false` at once;
/// the network coming up, or a read that failed unreachable, sends a probe of
/// the API origin, and an unanswered probe sends another a while later while
/// the network stays up. Nothing here exposes the kind, name or address of the
/// network.
abstract class DeviceConnectivity extends ChangeNotifier {
  /// [address] is the API origin's root a probe asks ([connectivityProbeAddress]),
  /// or `null` to follow the network alone.
  DeviceConnectivity(this._address);

  final Uri? _address;
  late final http.Client _client = http.Client();
  ConnectivityState _state = const ConnectivityState.initial(true);
  StreamSubscription<Object?>? _changes;
  Timer? _recheck;
  bool _probing = false;

  bool get isOnline => _state.isOnline;

  /// Reads whether the platform reports a network, then follows its changes.
  /// A check that fails reads as no network: being online is never assumed.
  Future<void> start() async {
    bool up;
    try {
      up = await networkUp();
    } on PlatformException catch (error) {
      _log.warning('The network check failed (${error.code}); the device reads as offline.');
      up = false;
    }
    _apply(ConnectivityState.initial(up));
    _changes ??= watchNetwork((up) => observe(up ? ConnectivityEvent.networkFound : ConnectivityEvent.networkLost));
  }

  /// Records that a read the app sent failed unreachable: the origin is checked
  /// again. With no API origin to check this changes nothing.
  void reportUnreachable() {
    if (_address != null) {
      observe(ConnectivityEvent.readUnreachable);
    }
  }

  /// Folds [event] through the rule, sending a probe when it says to.
  @visibleForTesting
  void observe(ConnectivityEvent event) {
    final next = connectivityStep(_state, event);
    _apply(next.state);
    if (!next.state.network) {
      _cancelRecheck();
    }
    if (next.probe) {
      unawaited(_probe());
    }
  }

  /// Whether the platform reports a network now.
  @protected
  Future<bool> networkUp();

  /// Calls [onChange] whenever the platform reports the network lost or found;
  /// `null` when it reports no changes.
  @protected
  StreamSubscription<Object?>? watchNetwork(void Function(bool up) onChange);

  /// Asks [address] whether it answers within [timeout].
  @protected
  Future<bool> probe(Uri address, Duration timeout) => probeOrigin(_client, address, timeout);

  Future<void> _probe() async {
    final address = _address;
    if (address == null || _probing) {
      return;
    }
    _probing = true;
    _cancelRecheck();
    bool answered;
    try {
      answered = await probe(address, connectivityProbeTimeout);
    } finally {
      _probing = false;
    }
    observe(answered ? ConnectivityEvent.probeAnswered : ConnectivityEvent.probeUnanswered);
    if (!answered && _state.network) {
      _recheck = Timer(connectivityRecheck, () {
        _recheck = null;
        unawaited(_probe());
      });
    }
  }

  void _apply(ConnectivityState state) {
    final changed = state.isOnline != _state.isOnline;
    _state = state;
    if (changed) {
      notifyListeners();
    }
  }

  void _cancelRecheck() {
    _recheck?.cancel();
    _recheck = null;
  }

  @override
  void dispose() {
    _cancelRecheck();
    unawaited(_changes?.cancel());
    super.dispose();
  }
}

