}

/// Every device capability of the runtime, checked again whenever the app
/// returns to the foreground. Listening to it rebuilds on any availability
/// or connectivity change.
class DeviceCapabilities extends ChangeNotifier with WidgetsBindingObserver {
  DeviceCapabilities({required this.media, required this.location, required this.share, required this.biometric, required this.notifications, required this.connectivity, required this.export}) {
    for (final capability in _checked) {
      capability.addListener(notifyListeners);
    }
    connectivity.addListener(notifyListeners);
  }

  final DeviceMedia media;
  final DeviceLocation location;
  final DeviceShare share;
  final DeviceBiometric biometric;
  final DeviceNotifications notifications;
  final DeviceConnectivity connectivity;
  final DeviceExport export;

  List<DeviceCapability> get _checked => [location, biometric, notifications];

  /// Checks every capability, and again on every return to the foreground,
  /// and starts following the network.
  Future<void> start() async {
    WidgetsBinding.instance.addObserver(this);
    await connectivity.start();
    await refresh();
  }

  Future<void> refresh() => Future.wait([for (final capability in _checked) capability.refresh()]);

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      unawaited(refresh());
    }
  }
}

/// What one app links of the device: the start-up its linked plugins need,
/// its capabilities, and the source of its push token.
abstract interface class DeviceLink {
  /// Readies the linked plugins once the runtime config loaded (Firebase is
  /// initialized with the registration it carries).
  Future<void> initialize(RuntimeConfig config);

  /// The app's capabilities: each linked one realized, every other unlinked.
  DeviceCapabilities capabilities(Nav nav, RuntimeConfig config);

  /// Where the app's push token comes from, or `null` when it links no push.
  PushTokenSource? pushTokens(RuntimeConfig config);
}

/// An app linking no device capability at all.
class UnlinkedDevice implements DeviceLink {
  const UnlinkedDevice();

  @override
  Future<void> initialize(RuntimeConfig config) async {}

  @override
  DeviceCapabilities capabilities(Nav nav, RuntimeConfig config) {
    return DeviceCapabilities(media: const UnlinkedMedia(), location: UnlinkedLocation(), share: UnlinkedShare(nav, config.webOrigin), biometric: UnlinkedBiometric(), notifications: UnlinkedNotifications(), connectivity: UnlinkedConnectivity(), export: const UnlinkedExport());
  }

  @override
  PushTokenSource? pushTokens(RuntimeConfig config) => null;
}
